void Solver::bump_var(int var, double coeff) {
    // Increase the activity of the variable proportionally to the coefficient.
    activity[var] += var_inc * coeff;

    // Prevent activity values from blowing up: if any activity exceeds a high threshold,
    // uniformly scale down all activities and the increment factor.
    const double MAX_ACTIVITY = 1e150;
    if (activity[var] > MAX_ACTIVITY) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Keep the VSIDS heap consistent: update if already present, otherwise insert.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}

