void Solver::restart() {
    // Reset LBD statistics more aggressively
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Backtrack to root level
    backtrack(0);

    // Aggressive rephasing: keep best phase most of the time,
    // occasionally invert it or choose a random polarity.
    int r = rand() % 100;
    if (r < 70) {
        // 70% keep the best local phase
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 85) {
        // 15% invert the best local phase
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // 15% assign a completely random phase
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() % 2) ? 1 : -1;
    }
}

